sys_script.script:
(function executeRule(current, previous) {

    gs.info('DEBUG Status Change: Business Rule started for Guest Case ' + current.getUniqueValue());

    var parentReq = new GlideRecord('x_snc_flowops_guest_request');

    gs.info('DEBUG Status Change: Parent Request sys_id = ' + current.getValue('parent_request'));

    if (!parentReq.get(current.getValue('parent_request'))) {
        gs.info('DEBUG Status Change: Parent Request not found. Exiting.');
        return;
    }

    gs.info('DEBUG Status Change: Parent Request found. Current parent status = ' + parentReq.getValue('status'));
    gs.info('DEBUG Status Change: Current Guest Case status = ' + current.getValue('status'));

    if (current.getValue('status') === 'in_progress' && parentReq.getValue('status') === 'routed') {

        gs.info('DEBUG Status Change: Guest Case is in_progress and Parent Request is routed.');
        gs.info('DEBUG Status Change: Updating Parent Request status to in_progress.');

        parentReq.setValue('status', 'in_progress');
        parentReq.update();

        gs.info('DEBUG Status Change: Parent Request successfully updated to in_progress.');
        return;
    }

    gs.info('DEBUG Status Change: Checking all sibling Guest Cases for resolution.');

    var allResolved = true;
    var siblingCases = new GlideRecord('x_snc_flowops_guest_case');

    siblingCases.addQuery('parent_request', current.getValue('parent_request'));
    siblingCases.query();

    var siblingCount = 0;

    while (siblingCases.next()) {

        siblingCount++;

        var status = siblingCases.getValue('status');

        gs.info(
            'DEBUG Status Change: Sibling Case ' +
            siblingCases.getUniqueValue() +
            ' has status = ' +
            status
        );

        if (status !== 'resolved' && status !== 'closed') {

            gs.info(
                'DEBUG Status Change: Sibling Case ' +
                siblingCases.getUniqueValue() +
                ' is not resolved/closed. Parent Request will remain unchanged.'
            );

            allResolved = false;
            break;
        }
    }

    gs.info('DEBUG Status Change: Total sibling cases checked = ' + siblingCount);
    gs.info('DEBUG Status Change: allResolved = ' + allResolved);

    if (allResolved && parentReq.getValue('status') !== 'resolved') {

        gs.info('DEBUG Status Change: All sibling cases are resolved/closed.');
        gs.info('DEBUG Status Change: Updating Parent Request status to resolved.');

        parentReq.setValue('status', 'resolved');
        parentReq.update();

        gs.info('DEBUG Status Change: Parent Request successfully updated to resolved.');

    } else {

        gs.info(
            'DEBUG Status Change: Parent Request not updated. ' +
            'allResolved = ' + allResolved +
            ', parent status = ' + parentReq.getValue('status')
        );
    }

    gs.info('DEBUG Status Change: Business Rule execution completed.');

})(current, previous);
